    morphology: "central coordinate graph with curve shifts and equilibrium markers",
    view: "the clearest scientifically appropriate teaching view",
    forbiddenShortcuts: [
      "generic icon",
      "unlabeled blob",
      "decorative geometry",
      "unrelated analogy object"
