      "supply shift left changes equilibrium",
      "final equality takeaway"
    ],
    reservedRegions: [
      { name: "title", x: 72, y: 38, w: 330, h: 46 },
      { name: "graph", x: 92, y: 132, w: 570, h: 342 },
      { name: "priceLabel", x: 102, y: 112, w: 74, h: 27 },
      { name: "quantityLabel", x: 470, y: 476, w: 109, h: 27 },
      { name: "supplyLabel", x: 548, y: 154, w: 74, h: 27 },
      { name: "demandLabel", x: 526, y: 414, w: 86, h: 27 },
      { name: "equilibriumLabel", x: 382, y: 274, w: 146, h: 27 },
      { name: "demandNote1", x: 700, y: 148, w: 164, h: 30 },
      { name: "demandNote2", x: 700, y: 182, w: 178, h: 30 },
      { name: "supplyNote1", x: 700, y: 294, w: 157, h: 30 },
      { name: "supplyNote2", x: 700, y: 328, w: 178, h: 30 },
      { name: "takeaway", x: 306, y: 458, w: 245, h: 27 }
    ]
  };

  const font =
    "Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif";
  const ink = "#1f2937";
  const paper = "#fbfbf8";
  const grid = "#d8d6cf";
  const teal = "#14b8a6";
  const blue = "#3b82f6";
  const rose = "#be185d";
  const green = "#65a30d";
  const amber = "#d97706";

  const demandMove = phase(p, 0.38, 0.64);
  const supplyMove = phase(p, 0.60, 0.84);
  const eqPulse = 1 + 0.35 * thereAndBackWithPause(phase(p, 0.76, 1));

  const E0 = { x: 378, y: 300 };
  const ED = { x: 450, y: 256 };
  const ES = { x: 310, y: 256 };

  const movingDemandDot = {
    x: lerp(E0.x, ED.x, demandMove),
    y: lerp(E0.y, ED.y, demandMove)
  };
  const movingSupplyDot = {
    x: lerp(E0.x, ES.x, supplyMove),
    y: lerp(E0.y, ES.y, supplyMove)
  };

  const textStyle = { fontFamily: font, fill: ink };
  const curveStyle = {
    fill: "none",
    strokeWidth: 5,
    strokeLinecap: "round",
    strokeLinejoin: "round"
  };

  return (
    <svg viewBox="0 0 1000 560" role="img" aria-label="Supply and demand graph">
      <defs>
        <marker id="arrowInk" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto">
          <path d="M 0 0 L 10 5 L 0 10 z" fill={ink} />
        </marker>
        <marker id="arrowBlue" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto">
          <path d="M 0 0 L 10 5 L 0 10 z" fill={blue} />
        </marker>
        <marker id="arrowRose" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto">
          <path d="M 0 0 L 10 5 L 0 10 z" fill={rose} />
        </marker>
        <marker id="arrowAmber" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto">
          <path d="M 0 0 L 10 5 L 0 10 z" fill={amber} />
        </marker>
      </defs>

      <rect x="0" y="0" width="1000" height="560" fill={paper} />
      <rect x="54" y="24" width="892" height="488" rx="18" fill="none" stroke={grid} strokeWidth="2" />

      <text
        x="72"
        y="70"
        fontSize="34"
        fontWeight="700"
        style={textStyle}
        data-teach-order={1}
        data-teach-kind="write"
        data-teach-weight={1.2}
        data-teach-sentence={1}
      >
        Supply and demand
      </text>

      <g
        data-teach-order={2}
        data-teach-kind="diagram"
        data-teach-weight={1}
        data-teach-sentence={1}
      >
        <line x1="130" y1="448" x2="130" y2="140" stroke={ink} strokeWidth="4" markerEnd="url(#arrowInk)" />
        <line x1="130" y1="448" x2="642" y2="448" stroke={ink} strokeWidth="4" markerEnd="url(#arrowInk)" />
        <line x1="130" y1="372" x2="622" y2="372" stroke="#e7e5dc" strokeWidth="2" />
        <line x1="130" y1="296" x2="622" y2="296" stroke="#e7e5dc" strokeWidth="2" />
        <line x1="130" y1="220" x2="622" y2="220" stroke="#e7e5dc" strokeWidth="2" />
        <line x1="258" y1="448" x2="258" y2="154" stroke="#e7e5dc" strokeWidth="2" />
        <line x1="386" y1="448" x2="386" y2="154" stroke="#e7e5dc" strokeWidth="2" />
        <line x1="514" y1="448" x2="514" y2="154" stroke="#e7e5dc" strokeWidth="2" />
      </g>

      <text
        x="102"
        y="130"
        fontSize="20"
        fontWeight="700"
        style={textStyle}
        data-teach-order={3}
        data-teach-kind="label"
        data-teach-weight={0.7}
        data-teach-sentence={1}
      >
        Price
      </text>

      <text
        x="470"
        y="492"
        fontSize="20"
        fontWeight="700"
        style={textStyle}
        data-teach-order={4}
        data-teach-kind="label"
        data-teach-weight={0.7}
        data-teach-sentence={1}
      >
        Quantity
      </text>

      <g
        data-teach-order={5}
        data-teach-kind="diagram"
        data-teach-weight={1}
        data-teach-sentence={1}
      >
        <path d="M 150 426 C 236 372, 352 282, 610 160" style={curveStyle} stroke={green} />
      </g>

      <text
        x="548"
        y="174"
        fontSize="21"
        fontWeight="700"
        fill={green}
        style={{ fontFamily: font }}
        data-teach-order={6}
        data-teach-kind="label"
        data-teach-weight={0.7}
        data-teach-sentence={1}
      >
        Supply
      </text>

      <g
        data-teach-order={7}
        data-teach-kind="diagram"
        data-teach-weight={1}
        data-teach-sentence={1}
      >
        <path d="M 155 170 C 270 214, 424 332, 610 426" style={curveStyle} stroke={teal} />
      </g>

      <text
        x="526"
        y="434"
        fontSize="21"
        fontWeight="700"
        fill={teal}
        style={{ fontFamily: font }}
        data-teach-order={8}
        data-teach-kind="label"
        data-teach-weight={0.7}
        data-teach-sentence={1}
      >
        Demand
      </text>

      <g
        data-teach-order={9}
        data-teach-kind="reveal"
        data-teach-weight={1}
        data-teach-sentence={4}
      >
        <line x1={E0.x} y1={E0.y} x2={E0.x} y2="448" stroke={amber} strokeWidth="3" strokeDasharray="7 7" />
        <line x1={E0.x} y1={E0.y} x2="130" y2={E0.y} stroke={amber} strokeWidth="3" strokeDasharray="7 7" />
        <circle cx={E0.x} cy={E0.y} r={8 * eqPulse} fill={amber} stroke={ink} strokeWidth="2" />
      </g>

      <text
        x="382"
        y="292"
        fontSize="20"
        fontWeight="700"
        fill={amber}
        style={{ fontFamily: font }}
        data-teach-order={10}
        data-teach-kind="label"
        data-teach-weight={0.9}
        data-teach-sentence={4}
      >
        Equilibrium Price
      </text>

      <g
        data-teach-order={11}
        data-teach-kind="diagram"
        data-teach-weight={1}
        data-teach-sentence={2}
      >
        <path
          d="M 260 170 C 360 218, 520 350, 680 430"
          style={curveStyle}
          stroke={blue}
          strokeDasharray="12 10"
          opacity={0.45 + 0.45 * demandMove}
        />
        <path d="M 352 246 C 386 236, 414 226, 444 216" fill="none" stroke={blue} strokeWidth="4" markerEnd="url(#arrowBlue)" />
        <circle cx={movingDemandDot.x} cy={movingDemandDot.y} r="6" fill={blue} />
        <circle cx={ED.x} cy={ED.y} r="7" fill={blue} stroke={ink} strokeWidth="2" opacity={0.55 + 0.45 * demandMove} />
      </g>

      <text
        x="700"
        y="172"
        fontSize="22"
        fontWeight="700"
        fill={blue}
        style={{ fontFamily: font }}
        data-teach-order={12}
        data-teach-kind="annotate"
        data-teach-weight={0.9}
        data-teach-sentence={2}
      >
        Demand right
      </text>

      <text
        x="700"
        y="206"
        fontSize="22"
        fontWeight="700"
        fill={blue}
        style={{ fontFamily: font }}
        data-teach-order={13}
        data-teach-kind="annotate"
        data-teach-weight={0.9}
        data-teach-sentence={2}
      >
        Price ↑, quantity ↑
      </text>

      <g
        data-teach-order={14}
        data-teach-kind="arrow"
        data-teach-weight={0.8}
        data-teach-sentence={2}
      >
        <path d="M 688 186 C 628 192, 574 218, 454 252" fill="none" stroke={blue} strokeWidth="3" markerEnd="url(#arrowBlue)" />
