      <g
        data-teach-order={15}
        data-teach-kind="diagram"
        data-teach-weight={1}
        data-teach-sentence={3}
      >
        <path
          d="M 110 420 C 210 360, 360 236, 530 160"
          style={curveStyle}
          stroke={rose}
          strokeDasharray="12 10"
          opacity={0.45 + 0.45 * supplyMove}
        />
        <path d="M 398 255 C 366 247, 337 241, 304 234" fill="none" stroke={rose} strokeWidth="4" markerEnd="url(#arrowRose)" />
        <circle cx={movingSupplyDot.x} cy={movingSupplyDot.y} r="6" fill={rose} />
        <circle cx={ES.x} cy={ES.y} r="7" fill={rose} stroke={ink} strokeWidth="2" opacity={0.55 + 0.45 * supplyMove} />
      </g>

      <text
        x="700"
        y="318"
        fontSize="22"
        fontWeight="700"
        fill={rose}
        style={{ fontFamily: font }}
        data-teach-order={16}
        data-teach-kind="annotate"
        data-teach-weight={0.9}
        data-teach-sentence={3}
      >
        Supply left
      </text>

      <text
        x="700"
        y="352"
        fontSize="22"
        fontWeight="700"
        fill={rose}
        style={{ fontFamily: font }}
        data-teach-order={17}
        data-teach-kind="annotate"
        data-teach-weight={0.9}
        data-teach-sentence={3}
      >
        Price ↑, quantity ↓
      </text>

      <g
        data-teach-order={18}
        data-teach-kind="arrow"
        data-teach-weight={0.8}
        data-teach-sentence={3}
      >
        <path d="M 688 333 C 610 322, 478 280, 318 260" fill="none" stroke={rose} strokeWidth="3" markerEnd="url(#arrowRose)" />
      </g>

      <g
        data-teach-order={19}
        data-teach-kind="annotate"
        data-teach-weight={0.8}
        data-teach-sentence={4}
      >
        <path d="M 300 470 C 334 454, 356 424, 376 310" fill="none" stroke={amber} strokeWidth="3" markerEnd="url(#arrowAmber)" />
      </g>

      <text
        x="306"
        y="478"
        fontSize="20"
        fontWeight="700"
        fill={ink}
        style={{ fontFamily: font }}
        data-teach-order={20}
        data-teach-kind="write"
        data-teach-weight={1}
        data-teach-sentence={4}
      >
        supplied = demanded
      </text>
    </svg>
  );
}
